import { templateSignature } from './industry-runtime.js';
export const EARTH_PRE_POPULATION_SIGNATURE='8d236561';
const ensure=(ok,message)=>{if(!ok)throw Error('지구 인구 업데이트: '+message);};
export function validatePopulationPackage(p){ensure(p?.schemaVersion===1&&p.kind==='earth-population-update'&&p.updateId==='ghsl-e2025-earth92-v1'&&p.gridFingerprint==='7d4c00a6'&&p.totalPersons===8893000000,'자료 버전/격자/총인구 불일치');ensure(p.before?.templateSignature===EARTH_PRE_POPULATION_SIGNATURE&&typeof p.after?.templateSignature==='string','공식 서명 불일치');for(const side of ['before','after']){const rows=p[side].populationPersons;ensure(rows&&Object.keys(rows).length===92,'92개 인구 필드 필요');ensure(Object.entries(rows).every(([id,n])=>/^sol:earth:surface:\d{5}$/.test(id)&&Number.isSafeInteger(n)&&n>=0),'ID/명수 오류');ensure(Object.values(rows).reduce((a,b)=>a+b,0)===p.totalPersons,'총인구 불일치');}ensure(Object.keys(p.before.populationPersons).sort().join()===Object.keys(p.after.populationPersons).sort().join(),'전/후 ID 불일치');return p;}
export function assertPopulationOnlyChange(before,after,p){validatePopulationPackage(p);ensure(before.systemId==='sol'&&before.bodyId==='earth'&&before.grid.gridFingerprint===p.gridFingerprint&&after.grid.gridFingerprint===p.gridFingerprint,'지구 원본 격자 불일치');const restored=structuredClone(after);for(const [id,n]of Object.entries(p.after.populationPersons)){ensure(before.startingScenario.cells[id]&&restored.startingScenario.cells[id]?.populationPersons===n,'허용 인구 필드 불일치');restored.startingScenario.cells[id].populationPersons=before.startingScenario.cells[id].populationPersons;}ensure(JSON.stringify(restored)===JSON.stringify(before),'인구 외 필드 변경 금지');return true;}
export function planEarthPopulation(before,p){validatePopulationPackage(p);const after=structuredClone(before);ensure(Object.keys(before.startingScenario.cells).length===92,'기존 92셀 시나리오 필요');for(const [id,n]of Object.entries(p.after.populationPersons)){ensure(after.startingScenario.cells[id],'구역 누락');after.startingScenario.cells[id].populationPersons=n;}assertPopulationOnlyChange(before,after,p);return after;}
export function canonicalPopulationMigration(state,catalog,p){
 if(!p||![1,2,3].includes(state?.schemaVersion)||state.kind!=='campaign-industry-runtime'||state.systemId!=='sol'||state.sourceSignatures?.earth!==EARTH_PRE_POPULATION_SIGNATURE)return null;
 validatePopulationPackage(p);const current=catalog.bodies.get('earth')?.template;if(!current||templateSignature(current)!==p.after.templateSignature)return null;
 const old=structuredClone(current);for(const [id,n]of Object.entries(p.before.populationPersons)){if(!old.startingScenario.cells[id])return null;old.startingScenario.cells[id].populationPersons=n;}if(templateSignature(old)!==EARTH_PRE_POPULATION_SIGNATURE)return null;assertPopulationOnlyChange(old,current,p);
 const next=structuredClone(state);next.sourceSignatures.earth=p.after.templateSignature;return next;
}
export function writePreservedBackup(storage,key,raw){const previous=storage.getItem(key);if(previous!==null&&previous!==raw)throw Error('기존 인구 업데이트 백업을 보존합니다: '+key);if(previous===null)storage.setItem(key,raw);}
